values
  ('CD', 'default', 'SYSCOHADA révisé — plan comptable général OHADA, Système normal', '{}'::jsonb, true, 'companies', array['CD-SYSCOHADA-BS', 'CD-SYSCOHADA-IS']::text[], null, 'Acte uniforme relatif au droit comptable et à l''information financière du 26 janvier 2017, art. 17, 7° — recours à un plan de comptes normalisé dont la liste figure dans le Système comptable OHADA ; Système comptable OHADA, Titre VII, chapitre 2, section 3 — liste des comptes, classes 1 à 8. La classe 9, engagements hors bilan et comptabilité analytique de gestion, est d''application facultative et n''est pas reprise. Commun aux dix-sept États parties : un seul fichier, packs/ohada/accounts.csv, recopié dans chaque pack par scripts/ohada-packs.mjs.', 'syscohada')
