insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CD', 'CD-P-16', 'Achats de biens 16 %', '{}'::jsonb, null, 'percent', 16, 'purchase', 'domestic', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 pour le taux ; art. 60-4° du décret n° 11/42 du 22 novembre 2011, cité par les extraits légaux de la DGI, pour la déduction sur facture normalisée portant le numéro d''impôt du fournisseur. Même réserve sur la date d''application effective qu''au code CD-S-16.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-P-16-IMMO', 'Immobilisations 16 %', '{}'::jsonb, null, 'percent', 16, 'purchase', 'domestic', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 pour le taux, sur les biens constituant des immobilisations. Même réserve sur la date d''application effective qu''au code CD-S-16.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-P-16-SRV', 'Services extérieurs 16 %', '{}'::jsonb, null, 'percent', 16, 'purchase', 'domestic', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 pour le taux ; art. 58, modifié par la loi de finances n° 22/071, art. 33 — la déduction suppose une facture normalisée. Même réserve sur la date d''application effective qu''au code CD-S-16.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-P-8', 'Achats de biens de première nécessité 8 %', '{}'::jsonb, null, 'percent', 8, 'purchase', 'domestic', date '2023-01-01', null, 'Ordonnance-loi n° 10/001, art. 35, dans la rédaction de la loi de finances n° 22/071, art. 30, sur la même liste de 24 positions tarifaires que le code CD-S-8.', 'S', null, 140, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2023', null, null, null, null),
  ('CD', 'CD-P-IMP-16', 'Importation 16 % (TVA liquidée par la DGDA)', '{}'::jsonb, null, 'percent', 16, 'purchase', 'import', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 pour le taux ; la TVA à l''importation est liquidée par la Direction Générale des Douanes et Accises (DGDA) et déduite sur la déclaration de mise à la consommation, d''après la fiche de recherche (§1 et §5) ; l''article précis fixant l''exigibilité et le mode de déduction à l''importation n''a pas été identifié dans un texte lu séparément de l''art. 35.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-S-16', 'Ventes de biens 16 %', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA facturée au compte 4431', 'percent', 16, 'sale', 'domestic', date '2010-08-20', null, 'Ordonnance-loi n° 10/001 du 20 août 2010, art. 35 — taux normal de 16 % applicable à toutes les opérations imposables hors taux réduit et taux zéro. Art. 78 — la loi entre en vigueur endéans dix-huit mois à dater de sa signature (soit au plus tard le 20 février 2012) ; la date exacte de son application effective n''a pas été confirmée dans une source primaire lue, voir le README du pack.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-S-16-SRV', 'Prestations de services 16 %', '{}'::jsonb, 'Prestations de services au taux normal, TVA facturée au compte 4432', 'percent', 16, 'sale', 'domestic', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 — taux normal de 16 %, comme pour les biens. Même réserve sur la date d''application effective qu''au code CD-S-16.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-S-8', 'Biens de première nécessité 8 %', '{}'::jsonb, 'Liste tarifaire de 24 positions : viandes bovines, porcines et de volaille, abats, poissons congelés, séchés et salés, riz, sucres, laits infantiles et préparations de lait, eaux de table, sel iodé, savons de ménage, allumettes', 'percent', 8, 'sale', 'domestic', date '2023-01-01', null, 'Ordonnance-loi n° 10/001, art. 35, dans la rédaction de la loi de finances n° 22/071 du 28 décembre 2022, art. 30 — taux réduit de 8 % sur la liste tarifaire de 24 positions ; en vigueur depuis le 1er janvier 2023. La liste exacte des 24 positions tarifaires n''a pas été retranscrite ligne à ligne depuis le texte de la loi : un vendeur applique le taux réduit seulement si le bien figure sur cette liste, ce que le document ne porte pas lui-même.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2023', null, null, null, null),
  ('CD', 'CD-S-8-SRV', 'Billets d''avion du trafic aérien national 8 %', '{}'::jsonb, null, 'percent', 8, 'sale', 'domestic', date '2023-01-01', null, 'Ordonnance-loi n° 10/001, art. 35, dans la rédaction de la loi de finances n° 22/071 du 28 décembre 2022, art. 30 — taux réduit de 8 % étendu aux billets d''avion du trafic aérien national, en vigueur depuis le 1er janvier 2023. Un vol international reste au taux normal ou au taux zéro selon l''art. 35 ; ce que ce code ne distingue pas lui-même.', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2023', null, null, null, null),
  ('CD', 'CD-S-EXO', 'Opération exonérée (art. 15)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 15 et suivants, section 3 « Des exonérations », dont l''art. 15-5 a été modifié par la loi de finances n° 22/071, art. 29 (importations de billets et d''intrants monétaires par l''Institut d''émission, devises par les banques). La liste complète et à jour des exonérations, article par article, n''a pas été reconstituée à partir des textes lus : ce code porte le principe de l''exonération, pas une position précise de la liste. Voir le README du pack.', 'E', null, 60, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null),
  ('CD', 'CD-S-EXP', 'Exportation taxée au taux zéro', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2010-08-20', null, 'Ordonnance-loi n° 10/001, art. 35 — taux zéro pour les exportations et opérations assimilées. Même réserve sur la date d''application effective qu''au code CD-S-16.', 'G', null, 50, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'ol10001', null, null, null, null)
on conflict (country, code) do update set
