insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CD', 'CD-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2010-08-20', null, 'Ordonnance-loi n° 10/001 du 20 août 2010, art. 60 — la déclaration est mensuelle, déposée au plus tard le 15 du mois suivant, en double exemplaire, accompagnée du paiement ; la mention « Néant » est obligatoire en l''absence d''opérations. Aucun autre régime ni cadence trimestrielle n''a été trouvé dans les textes lus. Le modèle imprimé de la déclaration et la numérotation de ses cases ne sont publiés dans aucune source officielle trouvée : les cases de ce fichier sont nommées d''après le contenu que l''art. 60 fait déclarer et d''après les taux de l''art. 35, non d''après un formulaire. Le projet de loi de finances pour 2026 (art. 38) reprend ce texte et ajoute une obligation de déclarer les livraisons à soi-même, non adoptée à la date de ce pack et non reprise ici.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Ordonnance-loi n° 10/001, art. 60 — déclaration au plus tard le 15 du mois qui suit.', 'ol10001', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

