update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Décret n° 23/10 du 03 mars 2023, art. 4 à 10, et circulaire ministérielle n° 005/CAB/MIN/FINANCES/2024 — la facture normalisée porte un numéro de série et un code d''authentification délivrés par le dispositif électronique fiscal (DEF) au moment de son émission ; extraits des dispositions légales de la DGI, renvoyant à l''art. 100 du Décret n° 11/42 du 22 novembre 2011 — date et numéro de série de la facture. Aucun texte lu n''impose explicitement une séquence continue ni sans trou pour la numérotation interne de l''entreprise, à la différence du Sénégal ; le format proposé ici le permet sans l''exiger.',
  numbering_source_key          = 'decret-facture',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = null,
  tax_point_legal_reference     = null,
  tax_point_source_key          = null,
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Ordonnance-loi n° 10/001, art. 58, 59 ter et 59 quater, modifiés par la loi de finances n° 22/071 du 28 décembre 2022, art. 33 à 35 — tout redevable délivre une facture normalisée produite par un dispositif électronique fiscal (DEF, physique — Unité de Facturation et Module de Contrôle de Facturation — ou dématérialisé — e-UF et e-MCF), enregistré et connecté au système de la DGI, ou un document en tenant lieu. Décret n° 23/10 du 03 mars 2023 pour les modalités techniques ; circulaire ministérielle n° 005/CAB/MIN/FINANCES/2024 pour l''obligation faite aux clients de n''accepter que des factures normalisées et les mesures dérogatoires ; obligation effective au 1er décembre 2025 pour tous les assujettis à la TVA selon un communiqué de la DGI rapporté par la presse (source secondaire, non retenue dans le registre). Ce n''est un profil ni un schéma d''échange au sens de la norme EN 16931 : c''est une clearance nationale par DEF/SFE homologué, avec code d''authentification et code QR délivrés par le dispositif, à l''entrée déjà connectée au système de la DGI — un mécanisme que ce socle ne sait pas exprimer (voir le README du pack et docs/international.md, section « From RD Congo »). `profile`, `mandatory_from`, `party_scheme` et `vat_scheme` restent vides faute d''un mécanisme de clearance à déclarer ici.',
  einvoice_source_key           = 'decret-facture',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CD';

