  ('CD', 'exempt', 'exempt', 'Opération exonérée de la taxe sur la valeur ajoutée — article 15 de l''Ordonnance-loi n° 10/001 du 20 août 2010.', '{}'::jsonb, 10, date '1970-01-01', null, 'Extraits des dispositions légales de la DGI, mentions obligatoires de la facture normalisée — montant non taxable de l''opération ; Ordonnance-loi n° 10/001, art. 15 et suivants, section 3 « Des exonérations ». La liste actualisée des exonérations n''a pas été entièrement reconstituée à partir des textes lus : voir le README du pack.'),
  ('CD', 'export', 'export', 'Exportation taxée au taux zéro — article 35 de l''Ordonnance-loi n° 10/001 du 20 août 2010.', '{}'::jsonb, 20, date '1970-01-01', null, 'Ordonnance-loi n° 10/001, art. 35 — taux zéro pour les exportations et opérations assimilées.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
